def apply(items: Sequence[Dict[str, Any]], overlays: Sequence[Dict[str, Any]]) -> List[Dict[str, Any]]:
    """overlays の置き換えを当てた写し。基の文が項目の中に1つだけでなければ止まる。"""
    out = copy.deepcopy(list(items))
    by_name = {it["名前"]: it for it in out}
    for ov in overlays:
        it = by_name[ov["項目"]]
        text = item_text(it)
        if text.count(ov["基の文"]) != 1:
            raise ValueError(f"{ov['id']}：基の文が「{ov['項目']}」に1つだけではありません")
        it["段落"] = text.replace(ov["基の文"], ov["混ぜた文"]).split("\n")
        for old, new in ov.get("根拠の置き換え", []):
            hits = [r for r in it["根拠"] if r["記述"] == old]
            if len(hits) != 1:
                raise ValueError(f"{ov['id']}：根拠の行「{old}」が1つだけではありません")
            hits[0]["記述"] = new
            hits[0]["照らす語"] = [new]
        it["根拠"].extend(copy.deepcopy(ov.get("足す根拠", [])))
    return out


