def plan_markdown(title: str, items: Sequence[Dict[str, Any]]) -> str:
    lines = [f"# 事業計画書（その1・その2）の本文：株式会社やまぶき惣菜（{MARK}）", "",
             f"省力化（一般型）第9回。{title}。Word には `make_plans.py` が公式の様式から書き込む（リポには入れない）。", ""]
    for it in items:
        lines += [f"## {it['名前']}", ""]
        for p in it["段落"]:
            lines += [p, ""]
    return "\n".join(lines)


