def plan_vs_actual() -> Dict[str, Any]:
    """計画と実績の差と、要件の判定（様式の別紙4 と同じ計算。lib/youken.py）。"""
    s = model_summary()
    plan = {k: s["合算"][k][1] for k in ("売上", "原材料費", "給与支給総額", "その他の人件費", "減価償却費", "その他の経費", "人件費", "営業利益")}
    a = dict(ACTUAL_YEAR1)
    a["人件費"] = a["給与支給総額"] + a["その他の人件費"]
    a["営業利益"] = a["売上"] - a["原材料費"] - a["人件費"] - a["減価償却費"] - a["その他の経費"]
    base_va = s["指標"]["付加価値額"][0]
    base_prod = s["指標"]["労働生産性"][0]
    base_pp = s["指標"]["1人当たり給与"][0]
    workers = a["役員数"] + a["常勤従業員数"]
    va = a["営業利益"] + a["人件費"] + a["減価償却費"]
    prod = youken.productivity(va, workers)
    pp = youken.pay_per_person(a["給与支給総額"], a["給与を受けた従業員数"])
    prod_g = youken.growth_plain(prod, base_prod, 1)
    pp_g = youken.growth_pay(pp, base_pp, 1)
    va_g = youken.growth_plain(va, base_va, 1)
    target_final = base_pp * (1 + float(TARGET_PAY_GROWTH) / 100) ** 5
    need = ((target_final / pp) ** (1 / 4) - 1) * 100
    rate = Decimal(str(pp_g)) / TARGET_PAY_GROWTH
    refund = int((GRANT - RAISE_OF_CAP) * (1 - rate))
    duties = {d["id"]: d for d in json.loads(DUTY_FILE.read_text(encoding="utf-8"))["項目"]}

    def pages(duty_id: str) -> List[str]:
        return [f"{x['資料']} p.{x['ページ']}" for x in duties[duty_id]["出典"]]

    rows = {}
    for k in plan:
        rows[k] = {"計画": round(plan[k]), "実績": a[k], "差": round(a[k] - plan[k]), "差の割合（%）": round((a[k] - plan[k]) / plan[k] * 100, 1)}
    ind = s["指標"]
    return {
        "年": 1,
        "行ごとの差（円）": rows,
        "指標": {
            "付加価値額": {"基準年度": round(base_va), "計画": round(ind["付加価値額"][1]), "実績": round(va)},
            "労働生産性": {"基準年度": base_prod, "計画": ind["労働生産性"][1], "実績": prod},
            "1人当たり給与支給総額": {"基準年度": base_pp, "計画": ind["1人当たり給与"][1], "実績": pp},
        },
        "要件": [
            {"名前": "労働生産性の年平均成長率（基本要件①）", "基準": "毎年4.0%以上", "計画の伸び（1年目）": ind["労働生産性の伸び"][1],
             "実績の伸び（1年目）": prod_g, "判定": "満たさない（1年目）",
             "返還の条件": "未達のときの返還の定めは、資料から読み取れない（義務と返還条件 G34）", "出典": pages("G34")},
            {"名前": "1人当たり給与支給総額の年平均成長率（基本要件②）", "目標値": f"{TARGET_PAY_GROWTH}%",
             "計画の伸び（1年目）": ind["1人当たり給与の伸び"][1], "実績の伸び（1年目まで）": pp_g,
             "判定": "このままでは目標値に届かない見込み（判定は事業計画期間の終わり）",
             "目標に届くのに要る伸び（残りの4年、毎年）": round(need, 2),
             "返還の条件": duties["G35"]["値"], "出典": pages("G35"),
             "返還額の例（最終年度まで同じ伸びなら）": {"達成率": float(rate), "式": "（補助金交付額 − 補助上限引き上げ額）×（1 − 達成率）",
                                       "補助金交付額": GRANT, "補助上限引き上げ額": RAISE_OF_CAP, "返還額": refund}},
            {"名前": "付加価値額の増加（その他の要件③）", "基準": "基準年度より増える", "実績の伸び（1年目）": va_g,
             "判定": "満たす（1年目は基準年度より増えた）"},
        ],
        "この材料で扱わないこと": "事業場内最低賃金（義務と返還条件 G36）は、その年の地域別最低賃金が要るので、実績に入れていない",
    }


# ---------------------------------------------------------------------------
# Word（公式の様式に書く。作ったもの/ に置き、リポには入れない）
# ---------------------------------------------------------------------------


def build_word(items: Sequence[Dict[str, Any]], form: bytes) -> bytes:
    positions = [(it["名前"], it["書き込む位置"]) for it in items]
    root = xml_spans.parse(yw.read_parts(form)[1][yw.DOC])
    for name, pos in positions:
        yw.check_position(root, pos, name)
    blob = form
    for it in items:
        blob, _ = yw.write_item(blob, it["書き込む位置"], item_text(it), it["名前"], other_positions=positions)
    return blob


def hand_edit(blob: bytes, old: str, new: str) -> bytes:
    """社長が Word で文字だけを打ち替えた形：本文の部品の、その文字の1か所だけを替える。"""
    _infos, parts = yw.read_parts(blob)
    data = parts[yw.DOC]
    o, n = escape(old).encode("utf-8"), escape(new).encode("utf-8")
    if data.count(o) != 1:
        raise ValueError(f"「{old}」が Word の本文に1つだけではありません（{data.count(o)}）")
    return yw.rebuild_zip(blob, {yw.DOC: data.replace(o, n)})


def build_words(out: Path) -> List[str]:
    """downloads/ の公式の様式に、計画書の本文を書き込んで out に置く。様式がなければ何もしない。"""
    if not FORM.exists():
        return []
    form = FORM.read_bytes()
    made = []
    variants = plan_variants()
    for key, items in variants.items():
        write_bytes(out / key / "その1・2.docx", build_word(items, form))
        write_bytes(out / key / "根拠対照表.xlsx", konkyo.build(evidence_rows(items)))
        made += [f"{key}/その1・2.docx", f"{key}/根拠対照表.xlsx"]
    tool = build_word(variants[PLAN_CORRECT], form)
    edited = hand_edit(tool, HAND_EDIT["ツールが書いた言い回し"], HAND_EDIT["社長が直した言い回し"])
    write_bytes(out / PLAN_EDITED / "その1・2_ツールが書いた版.docx", tool)
    write_bytes(out / PLAN_EDITED / "その1・2_社長が直した版.docx", edited)
    made += [f"{PLAN_EDITED}/その1・2_ツールが書いた版.docx", f"{PLAN_EDITED}/その1・2_社長が直した版.docx"]
    return made


